const now = new Date();
const isoDate = now.toISOString().slice(0, 10);
const nicheCatalog = [
  {
    key: 'history-power',
    label: 'Historia y decisiones de poder',
    audience: 'Publico adulto interesado en historia explicada con ritmo',
    topicSeeds: [
      'La historia real del Proyecto Manhattan',
      'Como una crisis de suministros cambia el curso de una guerra',
      'La decision politica que cambio la exploracion espacial',
      'El error estrategico que transformo un imperio en decadencia'
    ]
  },
  {
    key: 'science-breakthroughs',
    label: 'Ciencia, descubrimientos y errores famosos',
    audience: 'Audiencia de divulgacion, tecnologia y curiosidad',
    topicSeeds: [
      'El descubrimiento accidental que cambio la medicina moderna',
      'Como se construyo la primera inteligencia artificial util',
      'La carrera por resolver un problema cientifico imposible',
      'Experimentos fallidos que acabaron revolucionando la tecnologia'
    ]
  },
  {
    key: 'internet-systems',
    label: 'Internet, plataformas y sistemas que moldean la vida diaria',
    audience: 'Personas interesadas en tecnologia e historia digital',
    topicSeeds: [
      'Como nacieron los algoritmos de recomendacion modernos',
      'La historia de los sistemas que sostienen internet',
      'Por que algunas decisiones tecnicas marcan decadas enteras',
      'Errores de producto que redefinieron una industria digital'
    ]
  },
  {
    key: 'future-industries',
    label: 'Industrias del futuro y tecnologias emergentes',
    audience: 'Audiencia interesada en innovacion, negocio y tecnologia',
    topicSeeds: [
      'La guerra silenciosa por dominar la fabricacion de chips',
      'Como se construyen las empresas que controlan la IA moderna',
      'Las tecnologias que parecen hype pero pueden cambiar una industria',
      'La cadena oculta detras de la computacion global'
    ]
  }
];
const dayNumber = Math.floor(now.getTime() / 86400000);
const chosenNiche = nicheCatalog[Math.abs(dayNumber) % nicheCatalog.length];
const topic = chosenNiche.topicSeeds[Math.abs(dayNumber) % chosenNiche.topicSeeds.length];
return [{
  json: {
    run: {
      id: `run-${isoDate}`,
      date: isoDate,
      status: 'draft'
    },
    channel: {
      slug: 'youtube-longform-ai',
      name: 'YouTube Longform AI',
      language: 'es',
      timezone: 'Europe/Madrid'
    },
    niche: chosenNiche,
    config: {
      targetMinutes: 38,
      publishHourLocal: '18:00',
      llm: {
        provider: 'openai',
        model: 'gpt-4.1'
      },
      tts: {
        provider: 'elevenlabs',
        voiceId: 'set-in-n8n-credential-or-node'
      },
      subtitles: {
        provider: 'openai-stt',
        mode: 'word-level',
        style: 'kinetic-documentary'
      },
      visuals: {
        stockProvider: 'storyblocks-or-artgrid',
        heroProvider: 'runway-or-kling',
        scenesPerChapter: 9,
        preferredMix: {
          stockPremium: 0.55,
          motionGraphics: 0.15,
          aiImage: 0.10,
          heroAiVideo: 0.10,
          archiveStill: 0.10
        }
      },
      render: {
        provider: 'creatomate',
        subtitleBurnIn: true,
        chapterCards: true
      },
      youtube: {
        privacyStatus: 'private',
        categoryId: '27',
        defaultTags: ['documental', 'historia', 'ciencia', 'tecnologia', 'analisis', 'longform']
      },
      editorialPolicy: {
        forbiddenRepeatWindowDays: 180,
        minimumOriginalityScore: 85,
        targetVideosPerWeekPerNiche: 2,
        requireFreshAngle: true,
        requireMonetizationSafeScript: true
      }
    },
    workingTopic: {
      canonicalTopic: topic,
      userFacingTopic: topic,
      uniquenessHash: topic.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
      chosenBy: 'rotation-seed-mock'
    },
    prompts: {
      researchSystem: 'Eres un lead researcher de YouTube longform. Devuelve solo JSON valido, con enfoque editorial, fuentes y angulo no repetido.',
      researchUser: `Prepara un research pack para un video de 38 minutos sobre: ${topic}. Debes proponer un angulo original, evitar topicos repetidos, identificar hooks de retencion y devolver una lista de fuentes o categorias de fuentes a consultar.`,
      outlineSystem: 'Eres un guionista senior de documentales faceless para YouTube. Devuelve solo JSON valido, con estructura de retencion y sin relleno.',
      scriptSystem: 'Eres un head writer de YouTube longform. Devuelve solo JSON valido. El guion debe ser monetizable, limpio, claro, con ritmo y sin repetirse.'
    },
    integrations: {
      researchLlmEnabled: false,
      outlineLlmEnabled: false,
      scriptLlmEnabled: false,
      ttsEnabled: false,
      subtitleAlignmentEnabled: false,
      renderEnabled: false,
      youtubeUploadEnabled: false
    }
  }
}];

const data = $input.first().json;
const bannedPatterns = ['top 10 curiosidades', 'resumen generico', 'video sin angle'];
const editorialChecks = {
  nicheLocked: true,
  duplicateCheckImplementedInDb: false,
  requiresDbQuery: ['editorial_topics', 'content_runs'],
  forbiddenRepeatWindowDays: data.config.editorialPolicy.forbiddenRepeatWindowDays,
  originalityScoreTarget: data.config.editorialPolicy.minimumOriginalityScore,
  blockedPatterns: bannedPatterns
};
const monetizationChecklist = {
  avoidHarmfulClaims: true,
  avoidGraphicContent: true,
  avoidMedicalOrLegalClaimsWithoutContext: true,
  avoidCopyrightedFootageWithoutLicense: true,
  requireTransformativeNarrative: true
};
return [{ json: { ...data, editorialChecks, monetizationChecklist } }];

const data = $input.first().json;
const raw = data.output?.[0]?.content?.[0]?.text || data.body?.output_text || data.body?.choices?.[0]?.message?.content;
let research = null;
if (raw) {
  try { research = JSON.parse(raw); } catch (error) { research = null; }
}
if (!research) {
  research = {
    canonicalTopic: data.workingTopic.canonicalTopic,
    angle: `Explicar ${data.workingTopic.userFacingTopic} como una historia de decisiones, incentivos y consecuencias reales`,
    audience: data.niche.audience,
    sourcePlan: ['libros y papers base', 'fuentes periodisticas serias', 'cronologia historica', 'datos y contexto industrial'],
    retentionHooks: [
      'abrir con una consecuencia moderna del tema',
      'cerrar cada capitulo con una tension abierta',
      'alternar contexto humano con implicaciones actuales'
    ],
    originalityNotes: 'El angulo evita listas genericas y plantea una narrativa causal.',
    bannedRepetitions: ['no repetir ejemplos del canal en los ultimos 6 meses']
  };
}
return [{ json: { ...data, research } }];

const data = $input.first().json;
const raw = data.output?.[0]?.content?.[0]?.text || data.body?.output_text || data.body?.choices?.[0]?.message?.content;
let outline = null;
if (raw) {
  try { outline = JSON.parse(raw); } catch (error) { outline = null; }
}
if (!outline) {
  const chapterTitles = [
    'La promesa y el problema de origen',
    'El contexto que casi siempre se omite',
    'El primer punto de inflexion',
    'Las decisiones que aceleraron el cambio',
    'Los errores, mitos y conflictos',
    'Los actores clave y sus incentivos',
    'El impacto sobre el presente',
    'Lo que viene despues y por que deberia importarte'
  ];
  outline = {
    workingTitle: `${data.workingTopic.userFacingTopic}: la historia completa`,
    hook: `Lo que hoy parece inevitable en realidad nacio de una cadena de decisiones muy concretas.`,
    promise: `Al terminar entenderas ${data.workingTopic.userFacingTopic} desde el origen hasta su impacto actual.`,
    cta: 'Si quieres documentales largos con contexto y claridad, suscribete para el siguiente episodio.',
    chapters: chapterTitles.map((title, index) => ({
      chapterIndex: index + 1,
      title,
      objective: `Crear retencion y avanzar la historia con una pieza nueva de contexto en ${title.toLowerCase()}`,
      targetMinutes: index === 0 ? 4 : 4.25,
      retentionDevice: index % 2 === 0 ? 'open-loop' : 'reveal'
    }))
  };
}
return [{ json: { ...data, outline } }];

const data = $input.first().json;
const raw = data.output?.[0]?.content?.[0]?.text || data.body?.output_text || data.body?.choices?.[0]?.message?.content;
let script = null;
if (raw) {
  try { script = JSON.parse(raw); } catch (error) { script = null; }
}
if (!script) {
  script = {
    title: `${data.workingTopic.userFacingTopic}: historia completa en 38 minutos`,
    description: `Documental faceless de larga duracion sobre ${data.workingTopic.userFacingTopic}, con contexto, narrativa y analisis.`,
    hook: data.outline.hook,
    intro: `${data.outline.hook} En este video vamos a seguir el origen, el conflicto, los puntos de giro y las consecuencias modernas del tema.`,
    chapters: data.outline.chapters.map((chapter) => ({
      chapterIndex: chapter.chapterIndex,
      title: chapter.title,
      narration: `${chapter.title}. Aqui desarrollamos el contexto, explicamos por que esta etapa importa y cerramos conectando con la siguiente decision o consecuencia.`
    })),
    outro: data.outline.cta,
    monetizationSafety: {
      advertiserFriendly: true,
      sensitiveClaimsReviewed: true,
      copyrightedQuotesMinimized: true
    }
  };
}
return [{ json: { ...data, script } }];

const data = $input.first().json;
const scenes = [];
let sceneIndex = 1;
for (const chapter of data.outline.chapters) {
  for (let i = 0; i < data.config.visuals.scenesPerChapter; i++) {
    const visualType = i % 7 === 0
      ? 'hero_ai_video'
      : i % 5 === 0
        ? 'motion_graphic'
        : i % 3 === 0
          ? 'ai_image'
          : i % 2 === 0
            ? 'archive_still'
            : 'stock_premium';
    scenes.push({
      sceneIndex,
      chapterIndex: chapter.chapterIndex,
      chapterTitle: chapter.title,
      visualType,
      searchText: `${data.workingTopic.userFacingTopic} ${chapter.title}`,
      subtitleStyle: 'kinetic-documentary',
      narrationBeat: `Escena ${i + 1} del capitulo ${chapter.chapterIndex}.`,
      targetDurationSeconds: Math.round((chapter.targetMinutes * 60) / data.config.visuals.scenesPerChapter)
    });
    sceneIndex += 1;
  }
}
const assetPlan = scenes.map((scene) => ({
  sceneIndex: scene.sceneIndex,
  provider: scene.visualType === 'hero_ai_video' ? 'runway-or-kling' : (scene.visualType === 'stock_premium' ? 'storyblocks-or-artgrid' : 'internal-graphics-or-image-gen'),
  requestedType: scene.visualType,
  searchText: scene.searchText
}));
return [{ json: { ...data, scenes, assetPlan } }];

const data = $input.first().json;
const subtitleSegments = [];
let segmentIndex = 1;
for (const chapter of data.outline.chapters) {
  subtitleSegments.push({
    segmentIndex,
    startMs: (segmentIndex - 1) * 4000,
    endMs: (segmentIndex - 1) * 4000 + 3200,
    text: `${chapter.title}.`,
    emphasisWords: [chapter.title.split(' ')[0] || chapter.title],
    style: 'kinetic-documentary'
  });
  segmentIndex += 1;
}
return [{ json: { ...data, subtitleSegments } }];

const data = $input.first().json;
const issues = [];
if (!data.niche?.key) issues.push('No hay nicho seleccionado');
if (!data.research?.angle) issues.push('Falta angulo editorial');
if (!data.outline?.chapters?.length) issues.push('No hay outline');
if (!data.script?.chapters?.length) issues.push('No hay guion por capitulos');
if ((data.scenes || []).length < 50) issues.push('Demasiadas pocas escenas para un longform de 38 minutos');
if (!(data.subtitleSegments || []).length) issues.push('No hay subtitulos alineados');
if (data.integrations.researchLlmEnabled === false) issues.push('Research real no conectado');
if (data.integrations.scriptLlmEnabled === false) issues.push('Script real no conectado');
if (data.integrations.ttsEnabled === false) issues.push('TTS real no conectado');
if (data.integrations.subtitleAlignmentEnabled === false) issues.push('Subtitulos reales no conectados');
if (data.integrations.renderEnabled === false) issues.push('Render real no conectado');
if (data.integrations.youtubeUploadEnabled === false) issues.push('Upload real no conectado');
const youtubePackage = {
  title: data.script?.title || `${data.workingTopic.userFacingTopic}: historia completa`,
  description: [
    data.script?.description || `Documental sobre ${data.workingTopic.userFacingTopic}.`,
    '',
    'Capitulos previstos:',
    ...data.outline.chapters.map((chapter, index) => `${index + 1}. ${chapter.title}`)
  ].join('\n'),
  tags: data.config.youtube.defaultTags,
  privacyStatus: data.config.youtube.privacyStatus,
  categoryId: data.config.youtube.categoryId,
  scheduledForLocal: `${data.run.date} ${data.config.publishHourLocal}`
};
const assessment = {
  currentWorkflowWillGenerateProfessionalVideo: false,
  currentWorkflowIsMonetizableAsIs: false,
  reasons: [
    'El flujo base aun es una plantilla de orquestacion, no una pipeline conectada.',
    'No hay control real contra repeticion hasta consultar base de datos y backlog editorial.',
    'No hay stock premium ni render final conectados.',
    'No hay subtitulado real con timestamps por palabra.',
    'No hay QA de copyright, claims y narrativa final antes de publicar.'
  ]
};
const status = issues.length ? 'needs_review' : 'ready_for_production';
return [{ json: { ...data, youtubePackage, quality: { issues, status }, assessment } }];
